{
  "name": "Emergency department night shift",
  "brief": {
    "situation": "It is the night shift in a hospital emergency department, one round per hour, {$inputs.horizon} hours long. Patients arrive on their own, about {$inputs.arrival_rate} an hour on average, and each has an urgency level from 1 (most urgent) to 5 (least urgent). Nobody in the department controls the arrivals: who comes through the door and when is exactly the same whichever way the staff work, so two ways of running the shift can be compared on the same night.",
    "rules": "Triage: the triage nurse sees the patients who have just arrived and puts them into the waiting queue. Treatment: a doctor takes one waiting patient at a time and cannot start another until that patient's treatment is finished; treatment takes 3 hours for urgency 1 and 2, 2 hours for urgency 3, and 1 hour for urgency 4 and 5 (the treatment table input sets this). A patient who has waited more than {$inputs.leave_hours} hours without being seen leaves without being seen. Treatment in progress when the shift ends is not finished and stays in the department. Staff are told the shift length, so they can avoid starting work they cannot finish.",
    "roles": {
      "nurse": "You are the triage nurse. Every hour, triage the patients who have just arrived so that they join the waiting queue. Nobody can be treated before you have triaged them.",
      "doctor": "You are a doctor. Every hour you choose one waiting patient to treat, or none. You treat one patient at a time and cannot take a new patient while your current one is still in treatment. A lower urgency number means a more urgent patient; patients who have waited longest are closest to walking out."
    }
  },
  "clock": {"rounds": "$inputs.horizon", "unit": "hour"},
  "inputs": {
    "horizon": {"type": "int", "default": 12, "min": 1, "max": 72, "display": "number", "label": "Shift length (hours)"},
    "arrival_rate": {"type": "number", "default": 5, "min": 0, "max": 60, "display": "number", "label": "Mean arrivals per hour", "description": "Average patients per hour over the whole shift; hourly counts are drawn from a Poisson with this mean times the hourly profile factor."},
    "arrival_profile": {
      "type": "table", "display": "table", "label": "Hourly arrival profile",
      "description": "One row per shift hour giving a multiplier on the mean arrival rate. Hours with no row use factor 1. Does not depend on staff actions.",
      "fields": {"hour": {"type": "int", "required": true}, "factor": {"type": "number", "default": 1, "min": 0}},
      "default": [
        {"hour": 1, "factor": 1.3}, {"hour": 2, "factor": 1.2}, {"hour": 3, "factor": 1.1},
        {"hour": 4, "factor": 1.0}, {"hour": 5, "factor": 0.9}, {"hour": 6, "factor": 0.8},
        {"hour": 7, "factor": 0.7}, {"hour": 8, "factor": 0.7}, {"hour": 9, "factor": 0.8},
        {"hour": 10, "factor": 0.9}, {"hour": 11, "factor": 1.1}, {"hour": 12, "factor": 1.2}
      ]
    },
    "urgency_mix": {
      "type": "table", "display": "table", "label": "Urgency mix",
      "description": "Weight of each urgency level among arrivals (1 is most urgent).",
      "fields": {"urgency": {"type": "int", "required": true, "min": 1, "max": 5}, "weight": {"type": "number", "default": 1, "min": 0}},
      "default": [{"urgency": 1, "weight": 25}, {"urgency": 2, "weight": 25}, {"urgency": 3, "weight": 20}, {"urgency": 4, "weight": 15}, {"urgency": 5, "weight": 15}]
    },
    "treatment": {
      "type": "table", "display": "table", "label": "Treatment hours by urgency",
      "description": "Hours of treatment for each urgency level, measured from the hour the doctor starts.",
      "fields": {"urgency": {"type": "int", "required": true, "min": 1, "max": 5}, "hours": {"type": "int", "required": true, "min": 1}},
      "default": [{"urgency": 1, "hours": 3}, {"urgency": 2, "hours": 3}, {"urgency": 3, "hours": 2}, {"urgency": 4, "hours": 1}, {"urgency": 5, "hours": 1}]
    },
    "leave_hours": {"type": "number", "default": 4, "min": 0, "max": 24, "display": "number", "label": "Hours before a waiting patient leaves", "description": "A patient who has waited strictly more than this many hours without being seen leaves without being seen."},
    "doctors": {"type": "int", "default": 2, "min": 0, "max": 6, "display": "number", "label": "Doctors on shift"},
    "triage": {"type": "bool", "default": true, "display": "toggle", "label": "Triage nurse on duty", "description": "With the nurse on duty, new arrivals are triaged before they can be treated. Without, patients join the waiting queue as they arrive."}
  },
  "world": {
    "arrivals_by_hour": [],
    "arrivals_total": 0,
    "n": 0,
    "rate_this_hour": 0,
    "treated": 0,
    "lwbs": 0,
    "seen": 0,
    "wait_total": 0
  },
  "patterns": {
    "arrivals": {"kind": "counts", "dist": "poisson", "description": "Patients arriving in an hour: Poisson around the mean rate for that hour. Independent of anything the staff do."},
    "urgency": {"kind": "draw", "dist": "choice", "values": "$map($inputs.urgency_mix, $it.urgency)", "weights": "$map($inputs.urgency_mix, $it.weight)", "description": "Urgency level of one arrival, drawn from the urgency mix."}
  },
  "types": {
    "patient": {
      "props": {
        "urgency": {"type": "int", "default": 3, "min": 1, "max": 5},
        "arrived": {"type": "int", "default": 1},
        "status": {"type": "text", "default": "arriving", "values": ["arriving", "waiting", "in_treatment", "treated", "lwbs"]},
        "hours_left": {"type": "int", "default": 0},
        "seen_at": {"type": "int", "default": -1},
        "wait_hours": {"type": "int", "default": -1},
        "treated_by": {"type": "text", "default": ""},
        "treated_at": {"type": "int", "default": -1},
        "left_at": {"type": "int", "default": -1}
      }
    },
    "nurse": {"agent": true},
    "doctor": {"agent": true}
  },
  "entities": {"nurse_1": {"type": "nurse", "name": "Triage nurse"}},
  "population": [{"type": "doctor", "count": "$inputs.doctors", "name": "Doctor {$i}"}],
  "stages": [
    {
      "name": "triage",
      "when": "$inputs.triage",
      "actions": {"nurse": ["triage"]},
      "who": "$count(patient, $it.status == arriving) > 0",
      "max_actions": 3,
      "max_calls": 6,
      "brief": "Patients who have just walked in are waiting to be triaged. Put every one of them into the waiting queue."
    },
    {
      "name": "treat",
      "actions": {"doctor": ["treat"]},
      "who": "$count(patient, $it.status == waiting) > 0",
      "max_actions": 1,
      "max_calls": 6,
      "brief": "Choose at most one waiting patient to treat this hour. You cannot take a patient while yours is still in treatment. Urgency 1 is most urgent; the longest waiters leave soonest."
    }
  ],
  "events": [
    {
      "name": "arrivals",
      "phase": "start",
      "every": 1,
      "say": "Hour {$round}: {$world.n} patient(s) arrive.",
      "do": [
        "$world.rate_this_hour = $inputs.arrival_rate * $get($dict($inputs.arrival_profile, $text($it.hour), $it.factor), $text($round), 1)",
        "$world.n = $pattern.arrivals($world.rate_this_hour, $round)",
        {"create": "patient", "count": "$world.n", "props": {"urgency": "$pattern.urgency($round * 1000 + $i)", "arrived": "$round", "status": arriving}},
        {"if": "not $inputs.triage", "then": [{"each": "$filter(patient, $it.status == arriving)", "do": "$it.status = waiting"}]},
        "$world.arrivals_total += $world.n",
        "$world.arrivals_by_hour += $world.n"
      ]
    },
    {
      "name": "hours_pass",
      "phase": "start",
      "every": 1,
      "do": [
        {"each": "$filter(patient, $it.status == in_treatment)", "do": [
          "$it.hours_left -= 1",
          {"if": "$it.hours_left <= 0", "then": ["$it.status = treated", "$it.treated_at = $round", "$world.treated += 1"]}
        ]},
        {"each": "$filter(patient, $it.status == waiting)", "do": [
          {"if": "$round - $it.arrived > $inputs.leave_hours", "then": ["$it.status = lwbs", "$it.left_at = $round", "$world.lwbs += 1"]}
        ]}
      ]
    }
  ],
  "actions": {
    "triage": {
      "by": "nurse",
      "description": "Move newly arrived patients into the waiting queue so a doctor can see them.",
      "params": {
        "patients": {"type": "list", "items": {"type": "entity", "of": "patient", "where": "$it.status == arriving"}, "description": "The patients who have just arrived."}
      },
      "do": [{"each": "$params.patients", "do": "$it.status = waiting"}],
      "outcome": "Triaged {$len($params.patients)} patient(s); they are now in the waiting queue."
    },
    "treat": {
      "by": "doctor",
      "description": "Start treating one waiting patient. You are busy for the treatment's whole duration and cannot take another patient until it is finished.",
      "params": {
        "patient": {"type": "entity", "of": "patient", "where": "$it.status == waiting", "description": "The waiting patient to treat."}
      },
      "when": [{"expr": "$count(patient, $it.treated_by == $actor.id and $it.status == in_treatment) == 0", "why": "You are still treating a patient."}],
      "do": [
        "$wait = $round - $params.patient.arrived",
        "$dur = $get($dict($inputs.treatment, $text($it.urgency), $it.hours), $text($params.patient.urgency), 1)",
        "$params.patient.status = in_treatment",
        "$params.patient.treated_by = $actor.id",
        "$params.patient.hours_left = $dur",
        "$params.patient.seen_at = $round",
        "$params.patient.wait_hours = $wait",
        "$world.seen += 1",
        "$world.wait_total += $wait"
      ],
      "outcome": "You start treating {$params.patient.id} (urgency {$params.patient.urgency}), who waited {$round - $params.patient.arrived} hour(s). It takes {$get($dict($inputs.treatment, $text($it.urgency), $it.hours), $text($params.patient.urgency), 1)} hour(s); you are busy until it finishes."
    }
  },
  "views": {
    "new_arrivals": {"for": "nurse", "title": "Just arrived", "of": "patient", "where": "$it.status == arriving", "sort": "$it.urgency", "show": "{id} — urgency {urgency}", "empty": "Nobody has just arrived."},
    "queue": {"for": ["nurse", "doctor"], "title": "Waiting queue", "of": "patient", "where": "$it.status == waiting", "sort": "[$it.urgency, $it.arrived]", "show": "{id} — urgency {urgency}, waiting {$round - $it.arrived}h", "empty": "Nobody is waiting."},
    "my_patient": {"for": "doctor", "title": "Your patient", "of": "patient", "where": "$it.treated_by == $actor.id and $it.status == in_treatment", "show": "{id} — urgency {urgency}, {$it.hours_left}h of treatment left", "empty": "You are free to take a patient."},
    "in_treatment": {"for": ["nurse", "doctor"], "title": "In treatment", "of": "patient", "where": "$it.status == in_treatment", "sort": "$it.arrived", "show": "{id} — urgency {urgency}, with {$it.treated_by}, {$it.hours_left}h left", "empty": "Nobody is in treatment."},
    "shift": {"for": "all", "show": "Hour {$round} of {$inputs.horizon} · arrived so far {$world.arrivals_total} · treated {$world.treated} · left without being seen {$world.lwbs} · still in the department {$count(patient, $it.status == waiting or $it.status == in_treatment or $it.status == arriving)}"},
    "department": {"for": "spectator", "title": "Department", "of": "patient", "sort": "$it.arrived", "show": "{id} urgency {urgency} arrived h{arrived} status {status} waited {wait_hours} left {left_at}"}
  },
  "metrics": {
    "arrivals_this_hour": "$count(patient, $it.arrived == $round)",
    "waiting": "$count(patient, $it.status == waiting)",
    "in_treatment": "$count(patient, $it.status == in_treatment)",
    "treated": "$count(patient, $it.status == treated)",
    "left_without_being_seen": "$count(patient, $it.status == lwbs)",
    "mean_wait_so_far": "$avg(patient, $it.wait_hours, $it.seen_at >= 0)"
  },
  "outputs": {
    "arrivals_by_hour": {"expr": "$world.arrivals_by_hour", "type": "list", "description": "Patients who arrived in each hour, in order."},
    "patients_arrived": {"expr": "$count(patient)", "type": "int", "description": "Total patients who arrived during the shift."},
    "patients_treated": {"expr": "$count(patient, $it.status == treated)", "type": "int", "description": "Patients whose treatment finished."},
    "patients_left_without_being_seen": {"expr": "$count(patient, $it.status == lwbs)", "type": "int", "description": "Patients who walked out after waiting more than the leave threshold."},
    "patients_in_department_at_end": {"expr": "$count(patient, $it.status == waiting or $it.status == in_treatment or $it.status == arriving)", "type": "int", "description": "Patients still waiting or still in treatment when the shift ended."},
    "mean_wait_hours": {"expr": "$avg(patient, $it.wait_hours, $it.seen_at >= 0)", "type": "number", "description": "Average hours between arrival and being seen, over patients who were seen; null when nobody was seen."}
  },
  "invariants": [
    {"expr": "$count(patient, $it.status == treated) + $count(patient, $it.status == lwbs) + $count(patient, $it.status == waiting) + $count(patient, $it.status == in_treatment) + $count(patient, $it.status == arriving) == $count(patient)", "why": "Every patient is in exactly one state."},
    {"expr": "$count(patient, $it.status == in_treatment) <= $count(doctor)", "why": "No doctor treats more than one patient at a time."},
    {"expr": "$sum($world.arrivals_by_hour) == $count(patient)", "why": "The hourly arrival log accounts for every patient."},
    {"expr": "$world.treated == $count(patient, $it.status == treated)", "why": "The treated counter matches the finished patients."},
    {"expr": "$world.lwbs == $count(patient, $it.status == lwbs)", "why": "The walk-out counter matches the patients who left."},
    {"expr": "$all(patient, $it.seen_at < 0 or $it.wait_hours == $it.seen_at - $it.arrived)", "why": "A patient's recorded wait is the time between arrival and being seen."}
  ]
}
